SELECT 'gongkao', '近义关系', 'kp-xingce-judgement-analogy-semantic-synonym', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "近义关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "意思相近的词。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、高阶战法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当几个选项都是近义词时，比较【感情色彩】（褒贬中）和【程度轻重】！题干是褒义词，选项必须找褒义的近义词组合。"}]}]}$$ AS jsonb), NULL, '近义关系的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "近义关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_semantic_synonym", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
